      "tipo": "norma",
      "achados": [
        {
          "proposicao": "O trecho do RTSGI lista normas e práticas API relacionadas a inspeção, integridade, proteção catódica, aptidão para serviço, RBI e equipamentos diversos.",
          "trechos": [
            "E61190bb0cc9cbe28:0:698",
            "E61190bb0cc9cbe28:698:1396",
            "E61190bb0cc9cbe28:1396:2088"
          ],
          "condicoes": [
            "no contexto de referências bibliográficas ou normativas do RTSGI"
          ],
          "limites": [
            "não apresenta o conteúdo prescritivo do regulamento",
            "o regulamento é voltado a instalações terrestres, enquanto o recorte prioriza FPSO/FSO e sistemas associados"
          ]
        }
      ]
    },
    {
      "id": "E7596b6674bf88226",
      "pertinente": false,
      "tipo": "norma",
      "achados": [
        {
          "proposicao": "O trecho de norma DNV trata de exemplo de projeto e avaliação por fases para vasos compósitos, considerando fases de fabricação, instalação, teste e operação, além de modos de falha.",
          "trechos": [
            "E7596b6674bf88226:0:696",
            "E7596b6674bf88226:696:1393",
            "E7596b6674bf88226:1393:2091",
            "E7596b6674bf88226:2091:2287"
          ],
          "condicoes": [
            "aplicado a exemplo de vaso compósito descrito pela DNV"
          ],
          "limites": [
            "não é focado em documentação, inspeção em serviço ou enquadramento NR-13",
            "o exemplo exclui partes conectadas e informa que análise completa exigiria todas as partes e fases"
          ]
        }
      ]
    }
  ],
